module GitPullRequests
  # The "Changes" section under a pull request's description
  class Hooks < Redmine::Hook::ViewListener
    def view_issues_show_description_bottom(context = {})
      issue = context[:issue]
      return '' unless issue && PullRequest.pull_request?(issue)

      pr = PullRequest.new(issue)
      return '' if pr.repository && !User.current.allowed_to?(:view_changesets, pr.repository.project)

      context[:hook_caller].send(:render, partial: 'git_pull_requests/changes', locals: {pr: pr})
    rescue StandardError => e
      # A broken plugin (e.g. after a Redmine upgrade) mustn't break the issue page
      Rails.logger.error("git_pull_requests: ##{issue&.id}: #{e.class}: #{e.message}")
      failed
    end

    private

    def failed
      tag.hr +
        tag.div(class: 'pull-request-changes') do
          tag.p(tag.strong(l(:label_change_plural))) +
            tag.p('Something went wrong in the git_pull_requests plugin: the changes ' \
                  "can't be shown. Details are in the Redmine log.", class: 'nodata')
        end
    end
  end
end
